-- Aba Cultura: conteúdo da Central VAI (copiado do Notion em 26/11/2026).
-- Todo o time (administrador, líder, especialista e operacional) lê; só administradores alteram.
-- Pode rodar mais de uma vez sem erro: o conteúdo inicial só entra se ainda não existir (não sobrescreve edições).

create table if not exists public.v2_cultura (
  id text primary key,
  pai text references public.v2_cultura(id) on delete cascade,
  ordem integer not null default 0,
  tipo text not null check (tipo in ('pagina','base','item')),
  titulo text not null default '',
  icone text,
  dados jsonb not null default '{}'::jsonb,
  atualizado_em timestamptz not null default now(),
  atualizado_por uuid default auth.uid()
);
create index if not exists v2_cultura_pai on public.v2_cultura (pai);

create or replace function public.v2_cultura_antes() returns trigger
language plpgsql set search_path = public as $$
begin
  new.atualizado_em := now();
  new.atualizado_por := auth.uid();
  return new;
end $$;
drop trigger if exists v2_cultura_antes on public.v2_cultura;
create trigger v2_cultura_antes before insert or update on public.v2_cultura
  for each row execute function public.v2_cultura_antes();

alter table public.v2_cultura enable row level security;
drop policy if exists "v2_cultura_ler" on public.v2_cultura;
create policy "v2_cultura_ler" on public.v2_cultura for select to authenticated using (public.v2_time());
drop policy if exists "v2_cultura_criar" on public.v2_cultura;
create policy "v2_cultura_criar" on public.v2_cultura for insert to authenticated with check (public.v2_admin());
drop policy if exists "v2_cultura_alterar" on public.v2_cultura;
create policy "v2_cultura_alterar" on public.v2_cultura for update to authenticated using (public.v2_admin()) with check (public.v2_admin());
drop policy if exists "v2_cultura_excluir" on public.v2_cultura;
create policy "v2_cultura_excluir" on public.v2_cultura for delete to authenticated using (public.v2_admin());
revoke all on public.v2_cultura from anon;
grant select, insert, update, delete on public.v2_cultura to authenticated;
grant all on public.v2_cultura to service_role;

-- arquivos anexados pela aba (privados: só o time lê, só administradores enviam)
insert into storage.buckets (id, name, public) values ('cultura', 'cultura', false) on conflict (id) do nothing;
drop policy if exists "cultura_arquivos_ler" on storage.objects;
create policy "cultura_arquivos_ler" on storage.objects for select to authenticated
  using (bucket_id = 'cultura' and public.v2_time());
drop policy if exists "cultura_arquivos_enviar" on storage.objects;
create policy "cultura_arquivos_enviar" on storage.objects for insert to authenticated
  with check (bucket_id = 'cultura' and public.v2_admin());
drop policy if exists "cultura_arquivos_alterar" on storage.objects;
create policy "cultura_arquivos_alterar" on storage.objects for update to authenticated
  using (bucket_id = 'cultura' and public.v2_admin()) with check (bucket_id = 'cultura' and public.v2_admin());
drop policy if exists "cultura_arquivos_excluir" on storage.objects;
create policy "cultura_arquivos_excluir" on storage.objects for delete to authenticated
  using (bucket_id = 'cultura' and public.v2_admin());

-- conteúdo inicial (Central VAI do Notion)
insert into public.v2_cultura (id, pai, ordem, tipo, titulo, icone, dados)
select x->>'id', x->>'pai', (x->>'ordem')::int, x->>'tipo', x->>'titulo', x->>'icone', coalesce(x->'dados', '{}'::jsonb)
  from jsonb_array_elements($cultura$[{"id":"41d086c0ac1c81dd89a9c57523e7c836","pai":null,"ordem":0,"tipo":"pagina","titulo":"Central VAI","icone":"⚡","dados":{"html":"<div class=\"n-callout\" data-cor=\"blue\" data-icone=\"👋\"><p><b>Comece por aqui.</b> A Central VAI é a fonte única de informação do Grupo VAI: quem somos, como trabalhamos, nossos clientes, projetos e decisões. Se não está aqui, não está oficializado.</p></div><h2>Navegação</h2><div class=\"n-cols\"><div class=\"n-col\"><div class=\"n-page\"><a class=\"n-link\" data-pg=\"41d086c0ac1c816ba64ec5c813e41ccf\">🧭 A Empresa</a></div><div class=\"n-page\"><a class=\"n-link\" data-pg=\"41d086c0ac1c81068511cae506e41189\">👥 Pessoas</a></div></div><div class=\"n-col\"><div class=\"n-page\"><a class=\"n-link\" data-pg=\"41d086c0ac1c8138a9b2f5553027890e\">🤝 Clientes</a></div><div class=\"n-page\"><a class=\"n-link\" data-pg=\"41d086c0ac1c8139b1b4e878dea015b2\">📦 Projetos e Operação</a></div></div><div class=\"n-col\"><div class=\"n-page\"><a class=\"n-link\" data-pg=\"41d086c0ac1c81538341c10680016abc\">📈 Comercial</a></div><div class=\"n-page\"><a class=\"n-link\" data-pg=\"41d086c0ac1c814eb11bfee7ec32d5b5\">📊 Gestão</a></div></div></div><h2>Regras da Central</h2><ol><li>Toda ação tem dono e prazo, e vive em Tarefas e Plano de Ação.</li><li>Toda reunião relevante gera ata em Reuniões e Decisões, ligada ao cliente ou projeto.</li><li>Processo só é oficial com status <b>Oficial</b> na base Processos e Modelos.</li><li>Funil e números ficam no DataCrazy/BI. Aqui ficam os materiais, as decisões e a leitura dos resultados.</li></ol>"}},{"id":"41d086c0ac1c816ba64ec5c813e41ccf","pai":"41d086c0ac1c81dd89a9c57523e7c836","ordem":0,"tipo":"pagina","titulo":"A Empresa","icone":"🧭","dados":{"html":"<p>Quem somos, no que acreditamos e como o Grupo VAI está organizado. Leitura obrigatória no onboarding.</p><div class=\"n-page\"><a class=\"n-link\" data-pg=\"41d086c0ac1c813eb2aacb92e209538e\">🎯 Missão, visão e valores</a></div><div class=\"n-page\"><a class=\"n-link\" data-pg=\"41d086c0ac1c812aa574ea623b15817f\">📖 Jeito VAI e nossa história</a></div><div class=\"n-page\"><a class=\"n-link\" data-pg=\"41d086c0ac1c81adbaf7c20ad9b23444\">🧩 Os 4 negócios do Grupo VAI</a></div><div class=\"n-page\"><a class=\"n-link\" data-pg=\"41d086c0ac1c81b2844cfe96907ac896\">🏢 Organograma</a></div><div class=\"n-page\"><a class=\"n-link\" data-pg=\"41d086c0ac1c81948675f5aa4f3e6b7b\">🚀 Onboarding</a></div>"}},{"id":"41d086c0ac1c813eb2aacb92e209538e","pai":"41d086c0ac1c816ba64ec5c813e41ccf","ordem":0,"tipo":"pagina","titulo":"Missão, visão e valores","icone":"🎯","dados":{"html":"<h2>Missão</h2><blockquote data-cor=\"blue\"><p>Estruturar a operação comercial de empresas para que elas vendam com método, dados e gente preparada, e não no improviso.</p></blockquote><h2>Visão</h2><blockquote data-cor=\"green\"><p>Ser a referência em operação comercial para empresas em crescimento no Brasil, com R$ 200 milhões por ano vendidos pelas empresas que estruturamos.</p></blockquote><h2>Valores: o que não negociamos</h2><div class=\"n-tw\"><table><thead><tr><th>#</th><th>Valor</th><th>O que significa</th><th>Na prática</th></tr></thead><tbody><tr><td>01</td><td><b>Transparência</b></td><td>Coragem de falar com honestidade e empatia, mesmo quando a conversa é difícil.</td><td>Preferimos perder uma venda a prometer o que não vamos entregar.</td></tr><tr><td>02</td><td><b>Coerência</b></td><td>Praticamos o que vendemos, a começar por aqui dentro.</td><td>Se cobramos do cliente, cumprimos antes.</td></tr><tr><td>03</td><td><b>Responsabilidade pelo resultado</b></td><td>O resultado do cliente é o nosso resultado.</td><td>\"A minha parte eu já fiz\" não existe no Grupo VAI.</td></tr><tr><td>04</td><td><b>Respeito</b></td><td>Respeitamos cliente, colegas e gestores, valorizando cada pessoa e cada relação.</td><td>Resultado ou posição não compra o direito de tratar mal ninguém.</td></tr><tr><td>05</td><td><b>Crescimento coletivo</b></td><td>Compartilhamos conhecimento e multiplicamos aprendizado.</td><td>Quem guarda o que sabe não tem espaço no Grupo VAI.</td></tr></tbody></table></div>"}},{"id":"41d086c0ac1c812aa574ea623b15817f","pai":"41d086c0ac1c816ba64ec5c813e41ccf","ordem":1,"tipo":"pagina","titulo":"Jeito VAI e nossa história","icone":"📖","dados":{"html":"<div class=\"n-callout\" data-cor=\"blue\" data-icone=\"💬\"><p><b>Não vendemos mágica. Vendemos estrutura.</b> O que vendemos para fora, praticamos para dentro.</p></div><h2>Carta dos sócios</h2><p>Você não entrou numa empresa que promete resultado. Entrou numa empresa que constrói o processo que gera o resultado, e cobra a execução dele.</p><p>A régua é alta desde o primeiro dia. Não porque somos duros, mas porque nossos clientes nos contratam por isso.</p><p>Você não é um recurso em teste. É um integrante em formação. Bem-vindo(a) ao time.</p><p><i>Renan Bessa · Pedro Machado — Sócios, Grupo VAI</i></p><h2>Nossa origem: da porta para fora à porta para dentro</h2><ul><li><b>2018 —</b> Renan Bessa funda a Spirit, em Maranguape: marketing focado em social media e tráfego pago.</li><li><b>2024 — a virada.</b> A maior dor dos clientes não estava em gerar demanda, e sim no que acontecia depois: processos, rotinas e operação comercial. A dor não estava da porta para fora; estava da porta para dentro.</li><li>A Spirit se torna o <b>Grupo VAI</b>.</li></ul><h2>Os números que sustentam o discurso</h2><div class=\"n-tw\"><table><thead><tr><th>Número</th><th>O que representa</th></tr></thead><tbody><tr><td><b>+300</b></td><td>empresas com operação comercial transformada</td></tr><tr><td><b>+100</b></td><td>CRMs implantados pelo Brasil</td></tr><tr><td><b>R$ 10 mi</b></td><td>faturamento somado da carteira, por mês</td></tr><tr><td><b>+50h</b></td><td>de arquitetura e implantação por empresário</td></tr></tbody></table></div><div class=\"n-callout\" data-cor=\"yellow\" data-icone=\"⚠️\"><p>Números públicos, citáveis em conversa comercial. Número individual de cliente só com autorização.</p></div><h2>Jeito VAI: como a gente trabalha</h2><div class=\"n-tw\"><table><thead><tr><th>Princípio</th><th>O que quer dizer</th></tr></thead><tbody><tr><td><b>Executar é lei.</b></td><td>Menos justificativa, mais entrega. Prazo combinado é prazo cumprido.</td></tr><tr><td><b>Estrutura antes de esforço.</b></td><td>Aconteceu duas vezes, vira processo.</td></tr><tr><td><b>Dado na mesa.</b></td><td>Toda conversa sobre resultado começa pelo número.</td></tr><tr><td><b>Mudar rápido.</b></td><td>Testou, aprendeu, ajusta. Sem apego ao que não funciona.</td></tr><tr><td><b>Feedback é combustível.</b></td><td>No Momento, no Ritmo e com Profundidade.</td></tr><tr><td><b>Zero mediocridade.</b></td><td>Buscar a excelência em cada atitude, entrega e resultado.</td></tr></tbody></table></div><h2>Método VAI em uma página</h2><div class=\"n-tw\"><table><thead><tr><th>Ferramenta</th><th>Para quem</th><th>O que é</th></tr></thead><tbody><tr><td><b>BANT</b></td><td>SDR</td><td>Budget, Authority, Need, Timing: qualifica antes de passar o lead.</td></tr><tr><td><b>SPIN</b></td><td>Closer</td><td>Situação, Problema, Implicação, Necessidade: conduz o diagnóstico.</td></tr><tr><td><b>AVCR</b></td><td>Objeções</td><td>Acolher, Validar, Contextualizar, Reconduzir.</td></tr><tr><td><b>KPIs em 3 camadas</b></td><td>Indicadores</td><td>Atividade, Conversão e Resultado.</td></tr><tr><td><b>Feedback em 3 tipos</b></td><td>Gestão</td><td>Momento, Ritmo e Profundidade.</td></tr><tr><td><b>Passagem de bastão</b></td><td>Processo</td><td>O lead vai do SDR ao closer sem perder contexto.</td></tr></tbody></table></div><blockquote>\"Não controlo o resultado, eu controlo a execução.\"</blockquote>"}},{"id":"41d086c0ac1c81adbaf7c20ad9b23444","pai":"41d086c0ac1c816ba64ec5c813e41ccf","ordem":2,"tipo":"pagina","titulo":"Os 4 negócios do Grupo VAI","icone":"🧩","dados":{"html":"<div class=\"n-callout\" data-cor=\"gray\" data-icone=\"🚪\"><p>Quatro negócios, uma operação completa, uma mesma porta de entrada: todos começam pela pré-fase Venda → Projeto e os líderes reportam semanalmente ao Pedro.</p></div><div class=\"n-tw\"><table><thead><tr><th>Negócio</th><th>O que entrega</th><th>Líder</th><th>Duração</th></tr></thead><tbody><tr><td><b>VAI Acelerar</b> · Estruturação</td><td>Diagnóstico, planejamento e execução da operação comercial: playbook, indicadores, treinamento e acompanhamento</td><td>Isadora</td><td>Definida após o diagnóstico</td></tr><tr><td><b>Sales Hunter</b> · Contratação</td><td>Recrutamento exclusivo de vendedores, com processo próprio de 14 etapas</td><td>Marieline</td><td>60 dias</td></tr><tr><td><b>VAI Tech</b> · Tecnologia</td><td>Implantação de CRM (DataCrazy), automações, agentes de IA e BI comercial</td><td>Caio (CRM e IA) · Arthur (BI)</td><td>30 dias na implantação de CRM avulsa</td></tr><tr><td><b>Sales Tank</b> · BPO comercial</td><td>Operação terceirizada: SDR, closer, IA fora do horário, CRM, gestor e BI</td><td>Supervisor(a) de BPO (em contratação), sob o Pedro</td><td>Sem data de fim</td></tr></tbody></table></div><p>Processos detalhados de cada negócio: base <a class=\"n-link\" data-pg=\"41d086c0ac1c810692fae55e456fff7b\">Processos e Modelos</a>.</p>"}},{"id":"41d086c0ac1c81b2844cfe96907ac896","pai":"41d086c0ac1c816ba64ec5c813e41ccf","ordem":3,"tipo":"pagina","titulo":"Organograma","icone":"🏢","dados":{"html":"<div class=\"n-callout\" data-cor=\"yellow\" data-icone=\"⚠️\"><p><b>Organograma 2.0 — proposta em validação (nov/2026).</b> Os materiais de origem ainda divergem em alguns pontos (veja \"Divergências a decidir\" no fim da página). Até a validação, a referência é o Organograma 2.0.</p></div><h2>Organograma 2.0</h2><div class=\"n-file\" data-src=\"semente:Organograma_Grupo_VAI_2.0.pdf\" data-nome=\"Organograma_Grupo_VAI_2.0.pdf\">Organograma Grupo VAI 2.0 (proposta para validação)</div><h2>Estrutura: dois sócios-diretores, quatro verticais na Operação e staff terceirizado</h2><div class=\"n-cols\"><div class=\"n-col\"><h3>🔵 Renan · Diretor Comercial</h3><p>Sócio. Também é closer da VAI.</p><p><b>Comercial</b> (vendas e pós-venda do Grupo VAI)</p><ul><li>Renan — Closer</li><li>Carlos — Supervisor de Vendas (compartilhado com o Sales Tank) · em contratação</li><li>Lívia — Consultora de Vendas</li><li>Nova pessoa — Consultor(a) de Vendas · a contratar</li></ul></div><div class=\"n-col\"><h3>🟢 Pedro · Diretor Operacional</h3><p>Sócio. Também é consultor de Gestão e Performance no VAI Acelerar.</p><ul><li><b>Sales Hunter:</b> Marieline (Gestora de Projeto) · Sara (Assistente de Projeto, estágio)</li><li><b>VAI Acelerar:</b> Isadora (Gestora de Projeto + Analista de Dados na Tutoria) · Marieline (Consultora, compartilhada) · Pedro (Consultor de Gestão e Performance)</li><li><b>VAI Tech:</b> Caio (Especialista em Implantação · CRM e IA) · Arthur (Especialista em Implantação · CRM e IA + BI Comercial)</li><li><b>Sales Tank</b> (9 clientes ativos ou em implantação): Carlos (Supervisor) · Lara (SDR) · Débora (Consultora de Vendas + Social Media) · Fabrício (Consultor de Vendas) · Vaga 1 (a contratar) · Vaga 2 (a contratar em janeiro)</li></ul></div></div><p><b>Staff terceirizado:</b> Coffee (ADM · financeiro e contábil) · Neto (Marketing)</p><h2>Carteira do Sales Tank</h2><div class=\"n-callout\" data-cor=\"gray\" data-icone=\"📐\"><p>Premissa: 2 clientes por consultor(a) de vendas.</p></div><div class=\"n-tw\"><table><thead><tr><th>Pessoa</th><th>Função</th><th>Clientes</th></tr></thead><tbody><tr><td>Carlos</td><td>Supervisor de Vendas · gestão do time e dos clientes</td><td>Todos</td></tr><tr><td>Lara</td><td>SDR</td><td>CSA · CPA</td></tr><tr><td>Débora</td><td>Consultora de Vendas</td><td>Ivesp · Aikont</td></tr><tr><td>Fabrício</td><td>Consultor de Vendas</td><td>Prisma · Icaratur</td></tr><tr><td>Vaga 1</td><td>Consultor(a) de Vendas · a contratar</td><td>Cokitelitas · Coffee</td></tr><tr><td>Vaga 2</td><td>Consultor(a) de Vendas · a contratar em jan</td><td>Lapidar + novos clientes</td></tr></tbody></table></div><h2>Cargos e acesso ao VAI Projetos</h2><p>Cada pessoa tem um cargo e pode acumular funções; o acesso é a soma delas.</p><div class=\"n-tw\"><table><thead><tr><th>Nível</th><th>O que pode</th></tr></thead><tbody><tr><td><b>Administrador</b></td><td>Vê e edita tudo: modelos, equipe, qualquer projeto e travas.</td></tr><tr><td><b>Líder</b></td><td>Todos os projetos da sua vertical: monta, coloca responsáveis, libera travas.</td></tr><tr><td><b>Consultor / Especialista</b></td><td>Os projetos em que está: edita atividades, registra atas, lança dados.</td></tr><tr><td><b>Operacional</b></td><td>Só as próprias atividades: marca como feito, lança dados, preenche a ficha.</td></tr></tbody></table></div><div class=\"n-tw\"><table><thead><tr><th>Pessoa</th><th>Setor</th><th>Cargo</th><th>Outras funções</th><th>Acesso</th></tr></thead><tbody><tr><td>Renan</td><td>Sócio · Comercial</td><td>Diretor Comercial</td><td>Closer da VAI</td><td>Administrador</td></tr><tr><td>Pedro</td><td>Sócio · Operação</td><td>Diretor Operacional</td><td>Consultor de Gestão e Performance no VAI Acelerar</td><td>Administrador</td></tr><tr><td>Carlos</td><td>Comercial e Sales Tank</td><td>Supervisor de Vendas (em contratação)</td><td>Supervisiona o comercial da VAI e o time do BPO</td><td>Líder</td></tr><tr><td>Isadora</td><td>VAI Acelerar</td><td>Gestora de Projeto</td><td>Analista de Dados Comercial (Tutoria)</td><td>Líder</td></tr><tr><td>Marieline</td><td>Sales Hunter · VAI Acelerar</td><td>Gestora de Projeto</td><td>Consultora no VAI Acelerar</td><td>Líder</td></tr><tr><td>Caio</td><td>VAI Tech</td><td>Especialista em Implantação · CRM e IA</td><td>—</td><td>Especialista</td></tr><tr><td>Arthur</td><td>VAI Tech</td><td>Especialista em Implantação · CRM e IA</td><td>BI Comercial</td><td>Especialista</td></tr><tr><td>Lívia</td><td>Comercial</td><td>Consultora de Vendas</td><td>SDR, closer e pós-venda</td><td>Operacional</td></tr><tr><td>Sara</td><td>Sales Hunter</td><td>Assistente de Projeto (estágio)</td><td>—</td><td>Operacional</td></tr><tr><td>Lara</td><td>Sales Tank</td><td>SDR</td><td>—</td><td>Operacional</td></tr><tr><td>Débora · Fabrício</td><td>Sales Tank</td><td>Consultor(a) de Vendas</td><td>Débora: Social Media Grupo VAI</td><td>Operacional</td></tr><tr><td>Coffee · Neto</td><td>Staff</td><td>ADM terceirizado · Marketing terceirizado</td><td>—</td><td>Sem acesso</td></tr></tbody></table></div>"}},{"id":"41d086c0ac1c81948675f5aa4f3e6b7b","pai":"41d086c0ac1c816ba64ec5c813e41ccf","ordem":4,"tipo":"pagina","titulo":"Onboarding","icone":"🚀","dados":{"html":"<div class=\"n-callout\" data-cor=\"blue\" data-icone=\"👋\"><p><b>Bem-vindo(a) ao Grupo VAI.</b> Comece pelo deck abaixo, depois leia <a class=\"n-link\" data-pg=\"41d086c0ac1c812aa574ea623b15817f\">Jeito VAI e nossa história</a> e <a class=\"n-link\" data-pg=\"41d086c0ac1c813eb2aacb92e209538e\">Missão, visão e valores</a>.</p></div><h2>Deck de onboarding</h2><div class=\"n-file\" data-src=\"semente:Onboarding_Grupo_VAI.pdf\" data-nome=\"Onboarding_Grupo_VAI.pdf\">Onboarding Grupo VAI (nov/2026)</div><h2>Seus primeiros 90 dias</h2><div class=\"n-cols\"><div class=\"n-col\"><h3>30 dias · Entender</h3><ul><li>Conhecer os 4 negócios, o método e as ferramentas</li><li>Acompanhar os projetos da sua frente ao lado do coordenador</li><li>Feedback de Momento, no dia a dia</li></ul></div><div class=\"n-col\"><h3>60 dias · Assumir</h3><ul><li>Conduzir entregas com supervisão</li><li>Rodar os rituais da sua frente sem precisar de lembrete</li><li>Feedback de Ritmo com o coordenador</li></ul></div><div class=\"n-col\"><h3>90 dias · Responder</h3><ul><li>Responder por entregas da sua frente com autonomia</li><li>Propor uma melhoria de processo, documentada</li><li>Feedback de Profundidade com os sócios</li></ul></div></div><h2>Ferramentas e rituais</h2><div class=\"n-tw\"><table><thead><tr><th>Ferramentas</th><th>Para quê</th></tr></thead><tbody><tr><td>DataCrazy</td><td>Nosso CRM e o dos clientes</td></tr><tr><td>n8n e Make</td><td>Automações e integrações</td></tr><tr><td>Base44 e Lovable</td><td>Sistemas e ferramentas internas</td></tr><tr><td>Power BI</td><td>Dashboards e BI comercial</td></tr><tr><td>VAI Projetos</td><td>Gestão dos projetos de estruturação</td></tr></tbody></table></div><div class=\"n-tw\"><table><thead><tr><th>Rituais</th><th>Como funciona</th></tr></thead><tbody><tr><td>Relatório comercial diário</td><td>PDF por cliente e resumo no WhatsApp</td></tr><tr><td>Semana comercial</td><td>Vai de quinta a quinta</td></tr><tr><td>Auditoria semanal de CRM</td><td>Automações, agentes de IA e backlog</td></tr><tr><td>Reporte dos líderes ao Pedro</td><td>Toda terça, status por escrito até segunda à noite</td></tr><tr><td>Reunião de alinhamento</td><td>Dia, horário e participantes a definir</td></tr></tbody></table></div><h2>Combinados</h2><div class=\"n-cols\"><div class=\"n-col\"><h3>O que esperamos de você</h3><ul><li>Viver os valores desde o primeiro dia</li><li>Perguntar assim que a dúvida surgir, não deixar para depois</li><li>Registrar tudo no CRM e no VAI Projetos</li><li>Comunicação bem alinhada com a gestão</li></ul></div><div class=\"n-col\"><h3>O que você pode esperar de nós</h3><ul><li>Clareza sobre o que é esperado</li><li>Feedback frequente e honesto</li><li>Acesso às ferramentas e ao método</li><li>Espaço real para crescer</li></ul></div></div><h2>Quem procurar</h2><div class=\"n-tw\"><table><thead><tr><th>Assunto</th><th>Quem</th></tr></thead><tbody><tr><td>Dúvida de projeto</td><td>Coordenador da sua frente</td></tr><tr><td>Operação e rotina</td><td>Pedro</td></tr><tr><td>Cliente novo ou oportunidade</td><td>Renan</td></tr></tbody></table></div><h2>Checklist da primeira semana</h2><ul class=\"n-todo\"><li data-ok=\"0\">Assistir/ler o deck de onboarding</li><li data-ok=\"0\">Ler A Empresa (missão, Jeito VAI, os 4 negócios, organograma)</li><li data-ok=\"0\">Ler a descrição do seu cargo (Pessoas → Cargos)</li><li data-ok=\"0\">Ler os processos da sua frente (Processos e Modelos)</li><li data-ok=\"0\">Receber acessos: DataCrazy, VAI Projetos, Notion, WhatsApp</li></ul>"}},{"id":"41d086c0ac1c81068511cae506e41189","pai":"41d086c0ac1c81dd89a9c57523e7c836","ordem":1,"tipo":"pagina","titulo":"Pessoas","icone":"👥","dados":{"html":"<div class=\"n-callout\" data-cor=\"red\" data-icone=\"🔒\"><p><b>Acesso restrito.</b> Esta área pode conter dados pessoais e contratuais. Restrinja o compartilhamento desta página a sócios e gestão (Compartilhar → remover acesso geral do teamspace).</p></div><div class=\"n-page\"><a class=\"n-link\" data-pg=\"41d086c0ac1c819bad29ed26fc0d1623\">👤 Colaboradores</a></div><div class=\"n-page\"><a class=\"n-link\" data-pg=\"41d086c0ac1c81dbac6dc53cd43eaeba\">📘 Cargos</a></div><div class=\"n-page\"><a class=\"n-link\" data-pg=\"41d086c0ac1c81e09895c5aee47d0c5d\">↔️ Trilhas e Treinamentos</a></div><div class=\"n-page\"><a class=\"n-link\" data-pg=\"41d086c0ac1c813bb8f6cf17b383c6c8\">✅ Admissão</a></div>"}},{"id":"41d086c0ac1c819bad29ed26fc0d1623","pai":"41d086c0ac1c81068511cae506e41189","ordem":0,"tipo":"base","titulo":"Colaboradores","icone":"👤","dados":{"descricao":"Quem faz parte do Grupo VAI. Acesso restrito.","colunas":[{"k":"Nome","tipo":"titulo"},{"k":"Cargo","tipo":"rel","base":"41d086c0ac1c81dbac6dc53cd43eaeba"},{"k":"Negócio","tipo":"multi","opcoes":[{"nome":"Grupo VAI","cor":"gray"},{"nome":"VAI Acelerar","cor":"blue"},{"nome":"Sales Hunter","cor":"orange"},{"nome":"VAI Tech","cor":"purple"},{"nome":"Sales Tank","cor":"green"}]},{"k":"Status","tipo":"status","opcoes":[{"nome":"Em admissão","cor":"yellow"},{"nome":"Ativo","cor":"green"},{"nome":"Desligado","cor":"gray"}]},{"k":"Clientes atendidos","tipo":"rel","base":"41d086c0ac1c81bdab46f843abc1190b"},{"k":"E-mail","tipo":"email"},{"k":"Telefone","tipo":"tel"}],"ordem":null}},{"id":"41d086c0ac1c81dbac6dc53cd43eaeba","pai":"41d086c0ac1c81068511cae506e41189","ordem":1,"tipo