o":["41d086c0ac1c812aa9baf417971354b6"],"Negócio":["Sales Tank"],"Status":"Ativo","Clientes atendidos":["41d086c0ac1c8157992dcb290041e3bc","41d086c0ac1c818a9425cd5a38ac2a80"]},"html":"<p>Consultor de Vendas no BPO. Clientes: Prisma · Icaratur.</p>"}},{"id":"41d086c0ac1c81b9aac2c3694479db9a","pai":"41d086c0ac1c819bad29ed26fc0d1623","ordem":10,"tipo":"item","titulo":"Isadora","icone":null,"dados":{"props":{"Cargo":["41d086c0ac1c81caaa08e05868feb29b","41d086c0ac1c81d1b796c36dbd653495"],"Negócio":["VAI Acelerar","Sales Tank"],"Status":"Ativo","Clientes atendidos":["41d086c0ac1c8160853aea7fd9defd5e","41d086c0ac1c81a2b80bd097e57a56b2","41d086c0ac1c8174abc0d346f24d4304","41d086c0ac1c81058fa2c1d9f04f4e3a","41d086c0ac1c8157992dcb290041e3bc","41d086c0ac1c818a9425cd5a38ac2a80","41d086c0ac1c81309184f6c60e8ff73e","41d086c0ac1c810c96f9f2e391392adb","41d086c0ac1c81e3b66ec166e09548a9","41d086c0ac1c81df93ffc6fd8efb7eef","41d086c0ac1c818883d2d1c2a059edac"]},"html":"<p>Líder da Consultoria (VAI Acelerar) e dos projetos de BPO. Também Analista de Dados Comercial na Tutoria.</p>"}},{"id":"41d086c0ac1c81c38a2de6591c2e932b","pai":"41d086c0ac1c819bad29ed26fc0d1623","ordem":11,"tipo":"item","titulo":"Lara","icone":null,"dados":{"props":{"Cargo":["41d086c0ac1c8138be30eb2f9be49c1d"],"Negócio":["Sales Tank"],"Status":"Ativo","Clientes atendidos":["41d086c0ac1c8160853aea7fd9defd5e","41d086c0ac1c81a2b80bd097e57a56b2"]},"html":"<p>SDR. Clientes: CSA · CPA.</p>"}},{"id":"41d086c0ac1c81dda73edeb7ae2e7dac","pai":"41d086c0ac1c819bad29ed26fc0d1623","ordem":12,"tipo":"item","titulo":"Débora","icone":null,"dados":{"props":{"Cargo":["41d086c0ac1c812aa9baf417971354b6","41d086c0ac1c81589baeed688156d936"],"Negócio":["Sales Tank","Grupo VAI"],"Status":"Ativo","Clientes atendidos":["41d086c0ac1c8174abc0d346f24d4304","41d086c0ac1c81058fa2c1d9f04f4e3a","41d086c0ac1c81309184f6c60e8ff73e"]},"html":"<p>Consultora de Vendas no BPO (Ivesp · Aikont) + Social Media do Grupo VAI.</p>"}},{"id":"41d086c0ac1c810784cdeea8e88a32e4","pai":"41d086c0ac1c81dbac6dc53cd43eaeba","ordem":0,"tipo":"item","titulo":"Sócio e Coordenador Operacional","icone":"🟢","dados":{"props":{"Nível":"Diretoria","Missão do cargo":"Garantir que a entrega honra o que foi vendido.","Negócio":["Grupo VAI"],"Principais indicadores":"Resultado das unidades · margem · qualidade das entregas","Colaboradores":["41d086c0ac1c813e90e2f9b695d9d867"]},"html":"<h2>Responsabilidades</h2><ul><li>Operação e qualidade das quatro frentes</li><li>Contratações</li><li>Metas e meritocracia</li><li>Decisão de capacidade</li><li>Último degrau do escalonamento</li></ul><h2>Até onde vai</h2><ul><li><b>Decide:</b> contratação, time, data de início; aprova bonificação.</li><li><b>Não faz:</b> não executa a entrega no dia a dia; cobra os coordenadores e o supervisor.</li></ul><h2>Reporta a</h2><p>Sociedade.</p><h2>Medido por</h2><p>Resultado das unidades, margem, qualidade das entregas.</p>"}},{"id":"41d086c0ac1c812aa9baf417971354b6","pai":"41d086c0ac1c81dbac6dc53cd43eaeba","ordem":1,"tipo":"item","titulo":"Consultor(a) de Atendimento — Vendas (closer)","icone":"🤝","dados":{"props":{"Nível":"Operacional","Missão do cargo":"Conduzir o lead até a venda.","Negócio":["Sales Tank"],"Principais indicadores":"Vendas realizadas · conversão · ticket médio","Colaboradores":["41d086c0ac1c81dda73edeb7ae2e7dac","41d086c0ac1c81a9ad73d3485f6d37bc"]},"html":"<h2>Responsabilidades</h2><ul><li>Qualificar</li><li>Conduzir o diagnóstico (SPIN)</li><li>Tratar objeções (AVCR)</li><li>Enviar proposta, negociar e fechar</li><li>Follow-up e reativação</li><li>CRM em dia e relatório diário</li></ul><h2>Até onde vai</h2><ul><li><b>Decide:</b> negocia dentro da margem definida no manual do cliente.</li><li><b>Não faz:</b> não oferece condição fora do manual; não muda escopo.</li></ul><h2>Reporta a</h2><p>Supervisor(a) de BPO.</p><h2>Medido por</h2><p>Vendas realizadas, conversão, ticket médio.</p>"}},{"id":"41d086c0ac1c8138be30eb2f9be49c1d","pai":"41d086c0ac1c81dbac6dc53cd43eaeba","ordem":2,"tipo":"item","titulo":"Consultor(a) de Atendimento — SDR","icone":"📞","dados":{"props":{"Nível":"Operacional","Missão do cargo":"Transformar lead em visita agendada e qualificada.","Negócio":["Sales Tank"],"Principais indicadores":"Agendamentos qualificados · taxa de comparecimento","Colaboradores":["41d086c0ac1c81c38a2de6591c2e932b"]},"html":"<h2>Responsabilidades</h2><ul><li>Atender e qualificar leads (BANT)</li><li>Seguir a cadência</li><li>Agendar</li><li>Registrar tudo no CRM</li><li>Relatório diário</li></ul><h2>Até onde vai</h2><ul><li><b>Decide:</b> conduz a conversa dentro do script e da cadência.</li><li><b>Não faz:</b> não negocia nem fecha (quem fecha é o cliente); não muda script ou critério sem o supervisor.</li></ul><h2>Reporta a</h2><p>Supervisor(a) de BPO.</p><h2>Medido por</h2><p>Agendamentos qualificados e taxa de comparecimento.</p>"}},{"id":"41d086c0ac1c81589baeed688156d936","pai":"41d086c0ac1c81dbac6dc53cd43eaeba","ordem":3,"tipo":"item","titulo":"Social Media / Marketing","icone":"📣","dados":{"props":{"Nível":"Operacional","Missão do cargo":"Sustentar a presença e o conteúdo do Grupo VAI.","Negócio":["Grupo VAI"],"Principais indicadores":"Consistência e desempenho do conteúdo","Colaboradores":["41d086c0ac1c81dda73edeb7ae2e7dac","41d086c0ac1c81bbb292e38c77f2f8ed"]},"html":"<div class=\"n-callout\" data-cor=\"gray\" data-icone=\"👥\"><p>Quem ocupa: Débora (acúmulo) e Neto (PJ parceiro).</p></div><h2>Responsabilidades</h2><ul><li>Social media</li><li>Apoio de marketing à marca e à geração de demanda</li></ul><h2>Até onde vai</h2><ul><li><b>Decide:</b> executa o calendário de conteúdo.</li><li><b>Não faz:</b> não fala por produto ou comercial sem alinhamento.</li></ul><h2>Reporta a</h2><p>Pedro / sócios.</p><h2>Medido por</h2><p>Consistência e desempenho do conteúdo.</p>"}},{"id":"41d086c0ac1c81adb53ace6ffa2e8764","pai":"41d086c0ac1c81dbac6dc53cd43eaeba","ordem":4,"tipo":"item","titulo":"Supervisor(a) de BPO","icone":"🎧","dados":{"props":{"Nível":"Gestão","Missão do cargo":"Responder pela execução diária de todos os clientes de BPO.","Negócio":["Sales Tank"],"Principais indicadores":"% de clientes na meta · relatórios no prazo · CRM atualizado · pendências escalonadas no prazo","Colaboradores":["41d086c0ac1c81cb9508edcf70cebac8"]},"html":"<div class=\"n-callout\" data-cor=\"yellow\" data-icone=\"⚠️\"><p>Vaga em contratação. No Organograma 2.0: Carlos, como Supervisor de Vendas compartilhado entre Comercial e Sales Tank.</p></div><h2>Responsabilidades</h2><ul><li>Qualidade dos atendimentos</li><li>Feedback e cobrança do time</li><li>Indicadores e CRM em dia</li><li>Cobrança do cliente na operação</li><li>Mapa de capacidade</li><li>Apuração da bonificação</li><li>Participa da implantação de cada cliente novo</li></ul><h2>Até onde vai</h2><ul><li><b>Decide:</b> correções e prioridades do dia.</li><li><b>Não faz:</b> não muda metas, escopo nem data de início; não valida a própria apuração (Isa valida, Pedro aprova).</li></ul><h2>Reporta a</h2><p>Pedro.</p><h2>Medido por</h2><p>% de clientes na meta, relatórios no prazo, CRM atualizado, pendências escalonadas no prazo.</p>"}},{"id":"41d086c0ac1c81caaa08e05868feb29b","pai":"41d086c0ac1c81dbac6dc53cd43eaeba","ordem":5,"tipo":"item","titulo":"Coordenador(a) de Projeto","icone":"📁","dados":{"props":{"Nível":"Coordenação","Missão do cargo":"Conduzir os projetos da sua frente do início à entrega, no prazo e no padrão.","Negócio":["VAI Acelerar","Sales Hunter","VAI Tech","Sales Tank"],"Principais indicadores":"Prazo das entregas · indicadores do projeto · satisfação do cliente","Colaboradores":["41d086c0ac1c81b9aac2c3694479db9a","41d086c0ac1c81adba1eeb676024b709","41d086c0ac1c81119183fabcc0a15423","41d086c0ac1c815488fedef5dea769fc"]},"html":"<div class=\"n-callout\" data-cor=\"gray\" data-icone=\"👥\"><p>Quem ocupa: Mari (Sales Hunter), Isa (Consultoria/BPO), Caio (CRM), Arthur (BI). No Organograma 2.0 o título aparece como Gestor(a) de Projeto / Especialista em Implantação — ver divergências no Organograma.</p></div><h2>Responsabilidades</h2><ul><li>Planejar e tocar cada projeto</li><li>Conduzir onboarding, produto/ICP e documentação</li><li>Acompanhar indicadores</li><li>Cobrar entregas do cliente</li><li>Relatório e RMR</li></ul><h2>Até onde vai</h2><ul><li><b>Decide:</b> o andamento do projeto; aprova entregas da sua frente.</li><li><b>Não faz:</b> não muda escopo, preço nem data de início combinada; não contrata.</li></ul><h2>Reporta a</h2><p>Pedro.</p><h2>Medido por</h2><p>Prazo das entregas, indicadores do projeto, satisfação do cliente.</p>"}},{"id":"41d086c0ac1c81d0a6fce8753debdd4d","pai":"41d086c0ac1c81dbac6dc53cd43eaeba","ordem":6,"tipo":"item","titulo":"Assistente de Projeto","icone":"🗂️","dados":{"props":{"Nível":"Operacional","Missão do cargo":"Dar suporte operacional ao coordenador para o projeto rodar.","Negócio":["Sales Hunter"],"Principais indicadores":"Tarefas em dia · qualidade do apoio","Colaboradores":["41d086c0ac1c815ba006d99a94eb5668"]},"html":"<div class=\"n-callout\" data-cor=\"yellow\" data-icone=\"⚠️\"><p>Quem ocupa: a confirmar. A descrição de cargos e o Onboarding citam Beatriz; Produtos e Processos e o Organograma 2.0 citam Sara (estágio).</p></div><h2>Responsabilidades</h2><ul><li>Organização de materiais</li><li>Agenda e registros</li><li>Apoio em relatórios e no acompanhamento de tarefas</li></ul><h2>Até onde vai</h2><ul><li><b>Decide:</b> executa o que o coordenador define.</li><li><b>Não faz:</b> não decide sobre o projeto nem fala por ele com o cliente sem alinhamento.</li></ul><h2>Reporta a</h2><p>Coordenador(a) da frente.</p><h2>Medido por</h2><p>Tarefas em dia, qualidade do apoio.</p>"}},{"id":"41d086c0ac1c81d1b796c36dbd653495","pai":"41d086c0ac1c81dbac6dc53cd43eaeba","ordem":7,"tipo":"item","titulo":"Analista de Dados / BI","icone":"📊","dados":{"props":{"Nível":"Analista","Missão do cargo":"Transformar dados da operação em leitura de gestão.","Negócio":["VAI Tech","VAI Acelerar"],"Principais indicadores":"Painéis no ar e confiáveis · análises que viram ação","Colaboradores":["41d086c0ac1c81b9aac2c3694479db9a","41d086c0ac1c815488fedef5dea769fc"]},"html":"<div class=\"n-callout\" data-cor=\"gray\" data-icone=\"👥\"><p>Quem ocupa: Arthur (VAI Tech), com apoio da Isa na Consultoria.</p></div><h2>Responsabilidades</h2><ul><li>Painéis e BI comercial</li><li>Acompanhamento de indicadores</li><li>Identificação de desvios e tendências</li></ul><h2>Até onde vai</h2><ul><li><b>Decide:</b> entrega a análise e aponta o desvio.</li><li><b>Não faz:</b> a decisão sobre o que fazer é do coordenador ou dos sócios.</li></ul><h2>Reporta a</h2><p>Pedro (ou coordenador da frente).</p><h2>Medido por</h2><p>Painéis no ar e confiáveis, análises que viram ação.</p>"}},{"id":"41d086c0ac1c81e6b528f31fe5f0eaa5","pai":"41d086c0ac1c81dbac6dc53cd43eaeba","ordem":8,"tipo":"item","titulo":"Sócio Comercial","icone":"🔵","dados":{"props":{"Nível":"Diretoria","Missão do cargo":"Trazer cliente e garantir que a venda sustente a entrega.","Negócio":["Grupo VAI"],"Principais indicadores":"Vendas · ticket médio · previsão × realizado","Colaboradores":["41d086c0ac1c8100a9f1f127b6fca560"]},"html":"<h2>Responsabilidades</h2><ul><li>Prospecção e fechamento (closer)</li><li>Novos negócios</li><li>Relação com o mercado</li><li>Previsão de fechamentos</li><li>Preço e condição comercial</li></ul><h2>Até onde vai</h2><ul><li><b>Decide:</b> aprova proposta, preço e desconto.</li><li><b>Não faz:</b> não promete prazo de início fora do padrão sem a Isa; não conduz a entrega.</li></ul><h2>Reporta a</h2><p>Sociedade.</p><h2>Medido por</h2><p>Vendas, ticket médio, previsão × realizado.</p>"}},{"id":"41d086c0ac1c81f88442cf0a9ea7a0ab","pai":"41d086c0ac1c81dbac6dc53cd43eaeba","ordem":9,"tipo":"item","titulo":"Consultor(a) de Vendas do Grupo VAI","icone":"📝","dados":{"props":{"Nível":"Operacional","Missão do cargo":"Conduzir a venda dos serviços do próprio Grupo VAI, do contrato à passagem